types.prepare:
// The card only sees the letter; the code and mnemonic stay in the key until grading.
return {
  view: { letter: fields.letter },
  key: { code: fields.code, mnemonic: fields.mnemonic ?? "" },
};

template.css:
.mo-eyebrow { font-size: 0.72rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--highlight); margin-bottom: -0.75rem; }
.mo-letter { font: 600 5.5rem/1 var(--font-mono); text-align: center; margin: 0.5rem 0 0; }
.mo-tape { display: flex; align-items: center; justify-content: center; gap: 0.7rem; min-height: 2.6rem; }
.mo-empty { color: var(--muted-foreground); font-size: 0.9rem; }
.mo-sym { --c: var(--highlight); display: inline-block; height: 1.1rem; border-radius: 999px; background: var(--c);
  box-shadow: 0 0 6px color-mix(in oklab, var(--c) 80%, transparent), 0 0 18px color-mix(in oklab, var(--c) 45%, transparent); transition: transform 0.12s, filter 0.12s; }
.mo-sym.dot { width: 1.1rem; }
.mo-sym.dash { width: 3.3rem; }
.mo-sym.new { animation: mo-pop 0.28s cubic-bezier(.2, 1.6, .4, 1); }
.mo-sym.is-ok { --c: var(--success); }
.mo-sym.is-bad { --c: var(--danger); }
.mo-sym.is-missed { --c: var(--muted-foreground); opacity: 0.5; box-shadow: none; }
.mo-sym.lit { filter: brightness(1.6); transform: scale(1.18); }
@keyframes mo-pop { from { transform: scale(0.2); filter: brightness(2.2); } }
.mo-pad { display: grid; grid-template-columns: 1fr 1fr auto; gap: 0.6rem; max-width: 26rem; width: 100%; margin: 0 auto; }
.mo-key { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.55rem; height: 5.5rem; border-radius: var(--radius);
  border: 1px solid var(--border); background: color-mix(in oklab, var(--foreground) 4%, transparent); color: var(--muted-foreground); cursor: pointer; transition: background 0.1s, transform 0.08s; }
.mo-key:hover { background: color-mix(in oklab, var(--foreground) 9%, transparent); }
.mo-key:active, .mo-key.down { transform: scale(0.96); background: color-mix(in oklab, var(--highlight) 18%, transparent); }
.mo-key small { font-size: 0.75rem; }
.mo-del { width: 4rem; font-size: 1.3rem; }
.mo-result { display: flex; flex-direction: column; align-items: center; gap: 0.7rem; text-align: center; }
.mo-result .e-section-title { margin: 0.3rem 0 -0.2rem; }
.mo-lamp { flex: none; width: 3rem; height: 3rem; border-radius: 50%; background: color-mix(in oklab, var(--foreground) 10%, transparent); transition: background 0.05s, box-shadow 0.05s; }
.mo-lamp.on { background: #ffe9a8; box-shadow: 0 0 14px #ffd36a, 0 0 42px color-mix(in oklab, #ffb02e 70%, transparent); }

template.js:
const mine = etude.$(".mo-mine");
let seq = typeof etude.answer === "string" ? etude.answer : "";
const sym = (s, cls = "") => `<span class="mo-sym ${s === "." ? "dot" : "dash"} ${cls}"></span>`;

const draw = (fresh) => {
  mine.innerHTML = seq ? [...seq].map((s, i) => sym(s, fresh && i === seq.length - 1 ? "new" : "")).join("") : `<span class="mo-empty">Tap dot and dash</span>`;
  etude.setReady(seq.length > 0);
};
const press = (s) => {
  if (etude.mode !== "answer") return;
  seq = s === "del" ? seq.slice(0, -1) : (seq + s).slice(0, 7);
  draw(s !== "del");
};
etude.$$(".mo-key").forEach((b) => b.addEventListener("click", () => press(b.dataset.s)));
window.addEventListener("keydown", (e) => {
  const s = { ".": ".", "-": "-", j: ".", k: "-", Backspace: "del" }[e.key];
  if (!s || etude.mode !== "answer") return;
  e.preventDefault();
  press(s);
  const b = etude.$(`.mo-key[data-s="${s}"]`);
  b?.classList.add("down");
  setTimeout(() => b?.classList.remove("down"), 120);
});
draw(false);
etude.getAnswer(() => seq);

etude.onResult(({ key, answer }) => {
  const sent = String(answer ?? "");
  const code = key.code;
  // Your taps, marked symbol by symbol; anything you left out shows faded.
  mine.innerHTML = [...sent].map((s, i) => sym(s, s === code[i] ? "is-ok" : "is-bad")).join("") +
    [...code.slice(sent.length)].map((s) => sym(s, "is-missed")).join("");
  const right = etude.$(".mo-correct");
  right.innerHTML = [...code].map((s) => sym(s)).join("");
  // Blink the right code on the lamp at Morse timing: dot 1 unit, dash 3, gaps 1, then a pause.
  const lamp = etude.$(".mo-lamp");
  const parts = etude.$$(".mo-correct .mo-sym");
  const U = 170;
  const loop = (i) => {
    if (!lamp.isConnected) return;
    if (i === code.length) return setTimeout(() => loop(0), 6 * U);
    lamp.classList.add("on"); parts[i].classList.add("lit");
    setTimeout(() => {
      lamp.classList.remove("on"); parts[i].classList.remove("lit");
      setTimeout(() => loop(i + 1), U);
    }, code[i] === "." ? U : 3 * U);
  };
  setTimeout(() => loop(0), 400);
});

grader.code:
// answer is the tapped sequence, e.g. "-.-."
const sent = String(answer ?? "").replace(/[^.-]/g, "");
const ok = sent === key.code;
return {
  score: ok ? 1 : 0,
  details: { sent },
  feedback: ok ? undefined : `You sent ${sent || "nothing"}, but ${view.letter} is ${key.code}`,
};
